class Meta(HTMLParser):
 def __init__(self):super().__init__();self.meta={}
 def handle_starttag(self,t,a):
  d=dict(a)
  if t=='meta' and d.get('name','').startswith('citation_'):self.meta.setdefault(d['name'],[]).append(d.get('content','').strip())
