 s.update(title=m['citation_title'][0],authors=m.get('citation_author',[]),publication_date=m['citation_publication_date'][0],year=int(m['citation_publication_date'][0][:4]),access='full_document_retrieved',fulltext_path='fulltext/'+id+'.txt',license='CC-BY-4.0',license_url='https://creativecommons.org/licenses/by/4.0/',license_verified=True,rights_review='cleared_for_CC_BY_redistribution_with_attribution',retrieved_at='2026-10-25',read_scope='complete_main_text' if id in ['S17','S18'] else 'selected_methods_results_and_license',training_ready=False)
 text=(DOC/(id+'.txt')).read_text()
