 if start>=0:text=text[start+1:]
 notice='SOURCE: '+s['title']+'\nAUTHORS: '+'; '.join(s['authors'])+'\nDOI: '+s['doi']+'\nLICENSE: CC BY 4.0. Original publisher document; extracted text. No scientific corrections applied.\n\n'
 (FULL/(id+'.txt')).write_text(notice+text)
 (FULL/(id+'.txt.gz')).write_bytes(gzip.compress((notice+text).encode(),mtime=0))
 # license presence was inspected in each downloaded text; exact short locator preserved.
 s['license_locator']='Copyright/license statement at end of full article'
